export default `<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="referrer" content="no-referrer"><title>LightCity live audio test</title><style>body{font:18px/1.6 system-ui,sans-serif;background:#f5f5f5;color:#272727;margin:0}main{max-width:700px;margin:40px auto;padding:28px;background:white;border:1px solid #ddd;border-radius:22px}h1{font-size:32px;line-height:1.2}audio{width:100%;margin:20px 0}button{font:inherit;background:#ffbf00;border:0;border-radius:12px;padding:12px 24px;cursor:pointer}@media(max-width:750px){main{margin:20px 12px}}</style><main><small>LIGHTCITY · PRIVATE PHONE TEST</small><h1>Listen to the test feed.</h1><p id="status" role="status">Preparing audio…</p><audio controls preload="metadata"></audio><button type="button">Retry playback</button><p>Use headphones. You can try switching apps or locking your screen while listening.</p></main><script src="https://cdn.jsdelivr.net/npm/hls.js@1.7.3/dist/hls.min.js" referrerpolicy="no-referrer"></script><script>
(()=>{const p=new URLSearchParams(location.hash.slice(1)),session=p.get('session'),token=p.get('token'),audio=document.querySelector('audio'),status=document.querySelector('#status');history.replaceState(null,'',location.pathname);let hls=null,version=0;
function load(){const ticket=++version;hls?.destroy();audio.pause();audio.removeAttribute('src');audio.load();if(!/^session-\\d{13}$/.test(session||'')||!/^\\d{10}\\.[a-f0-9]{64}$/.test(token||'')){status.textContent='Open the private test link generated on your computer.';return;}const src='/live/'+session+'/audio.m3u8?token='+encodeURIComponent(token);status.textContent='Loading audio…';const ready=()=>{if(ticket===version)status.textContent='Ready. Press Play to listen.';};if(audio.canPlayType('application/vnd.apple.mpegurl')){audio.src=src;audio.addEventListener('loadedmetadata',ready,{once:true});}else if(window.Hls?.isSupported()){hls=new Hls({enableWorker:true,liveSyncDurationCount:3});hls.on(Hls.Events.MANIFEST_PARSED,ready);hls.on(Hls.Events.ERROR,(_,data)=>{if(ticket===version&&data.fatal)status.textContent='Audio unavailable. Check the uploader, or generate a fresh test link if this one has expired.';});hls.loadSource(src);hls.attachMedia(audio);}else status.textContent='The playback library could not load. Check your connection or try another browser.';}
audio.addEventListener('playing',()=>{status.textContent='Playing the private audio test.';if('mediaSession'in navigator){navigator.mediaSession.metadata=new MediaMetadata({title:'LightCity live audio test',artist:'LightCity Teaching Fellowship'});navigator.mediaSession.playbackState='playing';}});audio.addEventListener('pause',()=>{if('mediaSession'in navigator)navigator.mediaSession.playbackState='paused';});audio.addEventListener('error',()=>{status.textContent='Playback could not load. Check your connection or use a fresh test link.';});document.querySelector('button').addEventListener('click',load);addEventListener('pagehide',()=>{hls?.destroy();audio.pause();},{once:true});load();})();</script></html>`;
